 1	public final class ModularExponentiation {
 2	    private ModularExponentiation() {
 3	    }
 4	
 5	    public static int modPow(int base, int exponent, int modulus) {
 6	        validateInputs(exponent, modulus);
 7	
 8	        int normalizedBase = normalizeBase(base, modulus);
 9	        int remainingExponent = exponent;
10	        long result = 1 % modulus;
11	
12	        while (remainingExponent > 0) {
13	            if ((remainingExponent & 1) != 0) {
14	                result = multiplyMod(result, normalizedBase, modulus);
15	            }
16	
17	            normalizedBase = multiplyMod(normalizedBase, normalizedBase, modulus);
18	            remainingExponent >>= 1;
19	        }
20	
21	        return (int) result;
22	    }
23	
24	    public static int powMod(int base, int exponent, int modulus) {
25	        return modPow(base, exponent, modulus);
26	    }
27	
28	    private static void validateInputs(int exponent, int modulus) {
29	        if (exponent < 0) {
30	            throw new IllegalArgumentException("Exponent must be non-negative.");
31	        }
32	
33	        if (modulus <= 0) {
34	            throw new IllegalArgumentException("Modulus must be positive.");
35	        }
36	    }
37	
38	    private static int normalizeBase(int base, int modulus) {
39	        int normalizedBase = base % modulus;
40	        if (normalizedBase < 0) {
41	            normalizedBase += modulus;
42	        }
43	        return normalizedBase;
44	    }
45	
46	    private static int multiplyMod(long left, long right, int modulus) {
47	        return (int) ((left * right) % modulus);
48	    }
